@extends('crm.layout')
@section('content')
<style>
.lp{--navy:#10284b;--blue:#1f5fd0;--red:#d91f43;--muted:#74839a;--line:#e2e9f2}.lp-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:18px}.lp-eye{display:flex;align-items:center;gap:8px;color:#2362c7;font-size:10px;font-weight:800;letter-spacing:.09em;text-transform:uppercase}.lp-eye:before{content:"";width:28px;height:3px;border-radius:9px;background:#e43c46}.lp-head h1{margin:7px 0 5px;color:var(--navy);font-size:30px}.lp-head p{margin:0;color:var(--muted);font-size:13px}.lp-range{display:flex;gap:8px;align-items:center}.lp-range input,.lp-range select,.lp-filter{border:1px solid #dfe7f1;border-radius:10px;background:#fff;padding:9px 10px;font-size:11px;color:#2e435e}.lp-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}.lp-kpi{background:#fff;border:1px solid var(--line);border-radius:15px;padding:17px 18px;box-shadow:0 5px 18px rgba(18,40,75,.035)}.lp-kpi small{display:block;color:#74839a;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.045em}.lp-kpi b{display:block;margin-top:7px;color:var(--navy);font-size:27px}.lp-tabs{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:14px}.lp-tab{border:1px solid #dfe7f1;background:#fff;color:#53657d;border-radius:10px;padding:9px 13px;font-size:11px;font-weight:700;cursor:pointer}.lp-tab.active{background:#112d52;color:#fff;border-color:#112d52}.lp-card{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 5px 18px rgba(18,40,75,.03)}.lp-card-h{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:15px 17px;border-bottom:1px solid #edf1f6}.lp-card-h b{color:var(--navy);font-size:13px}.lp-tools{display:flex;gap:7px;flex-wrap:wrap}.lp-table-wrap{overflow:auto}.lp-table{width:100%;border-collapse:collapse;min-width:980px}.lp-table th{padding:10px 13px;background:#fafbfd;border-bottom:1px solid #e8edf4;color:#8290a3;font-size:8.5px;text-transform:uppercase;letter-spacing:.05em;text-align:left}.lp-table td{padding:12px 13px;border-bottom:1px solid #edf1f5;font-size:11px;color:#314660;vertical-align:middle}.lp-table tr:last-child td{border-bottom:0}.lp-id{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10px;color:#53657d}.lp-path{max-width:270px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#173758;font-weight:650}.lp-status{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:99px;font-size:9px;font-weight:800}.lp-status:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.lp-active{background:#eaf8ef;color:#15924a}.lp-idle{background:#fff7dd;color:#b87908}.lp-offline{background:#eef1f5;color:#6f7c8c}.lp-btn{display:inline-flex;align-items:center;gap:6px;border:0;border-radius:9px;padding:7px 10px;background:#112d52;color:#fff;font-size:9px;font-weight:800;text-decoration:none;cursor:pointer}.lp-btn.alt{background:#f1f5fa;color:#24486f}.lp-empty{padding:40px;text-align:center;color:#8795a8;font-size:11px}.lp-panel{display:none}.lp-panel.active{display:block}.lp-analytics{display:grid;grid-template-columns:1fr 1fr;gap:14px}.lp-mini{background:#fff;border:1px solid var(--line);border-radius:15px;padding:16px}.lp-mini h3{margin:0 0 12px;color:var(--navy);font-size:13px}.lp-list{display:grid;gap:8px}.lp-row{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid #eef2f6;font-size:10px;color:#53657d}.lp-row:last-child{border:0}.lp-row b{color:#183655}.lp-heat{position:relative;min-height:520px;border:1px dashed #ccd7e5;border-radius:12px;background:linear-gradient(#fbfcfe,#f5f8fc);overflow:hidden}.lp-dot{position:absolute;width:22px;height:22px;border-radius:50%;transform:translate(-50%,-50%);background:rgba(217,31,67,.22);border:1px solid rgba(217,31,67,.5)}.lp-drawer{position:fixed;z-index:10080;top:0;right:-520px;width:min(500px,96vw);height:100vh;background:#fff;box-shadow:-20px 0 60px rgba(10,29,54,.22);transition:right .22s ease;overflow:auto}.lp-drawer.open{right:0}.lp-drawer-h{position:sticky;top:0;background:#fff;border-bottom:1px solid #e8edf4;padding:18px;display:flex;justify-content:space-between;align-items:center;z-index:2}.lp-drawer-b{padding:18px}.lp-close{border:0;background:#eef3f8;border-radius:9px;width:34px;height:34px}.lp-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.lp-detail{border:1px solid #e7edf4;border-radius:11px;padding:10px}.lp-detail small{display:block;color:#8795a8;font-size:8px;text-transform:uppercase}.lp-detail b{display:block;color:#1c3857;font-size:10px;margin-top:4px;word-break:break-word}.lp-timeline{margin-top:16px}.lp-step{position:relative;padding:0 0 14px 20px;border-left:1px solid #dbe4ef;color:#53657d;font-size:10px}.lp-step:before{content:"";position:absolute;left:-4px;top:2px;width:7px;height:7px;border-radius:50%;background:#2c68ca}.lp-step b{display:block;color:#173758;margin-bottom:3px}.lp-load{padding:35px;text-align:center;color:#73839a;font-size:11px}@media(max-width:1100px){.lp-kpis{grid-template-columns:repeat(3,1fr)}.lp-analytics{grid-template-columns:1fr}.lp-head{flex-direction:column}}@media(max-width:720px){.lp-kpis{grid-template-columns:1fr 1fr}.lp-range{flex-wrap:wrap}.lp-detail-grid{grid-template-columns:1fr}}
</style>
<div class="lp" id="livePaxApp">
 <div class="lp-head"><div><div class="lp-eye">Website Intelligence</div><h1>Live Pax Monitor</h1><p>Live sessions, privacy-safe replay, journeys and friction signals. Tracking failures never block booking.</p></div><div class="lp-range"><button class="lp-tab" data-quick="today">Today</button><button class="lp-tab" data-quick="7">7 Days</button><button class="lp-tab" data-quick="30">30 Days</button><input type="date" id="lpFrom"><span>→</span><input type="date" id="lpTo"><button class="lp-btn" id="lpApply">Apply</button></div></div>
 <div class="lp-kpis"><div class="lp-kpi"><small>Online Now</small><b id="kOnline">0</b></div><div class="lp-kpi"><small>Active</small><b id="kActive">0</b></div><div class="lp-kpi"><small>Idle</small><b id="kIdle">0</b></div><div class="lp-kpi"><small>On Flight Results</small><b id="kResults">0</b></div><div class="lp-kpi"><small>On Payment</small><b id="kPayment">0</b></div></div>
 <div class="lp-tabs"><button class="lp-tab active" data-tab="live">Live Sessions</button><button class="lp-tab" data-tab="recorded">Recorded Sessions</button><button class="lp-tab" data-tab="journeys">Journeys</button><button class="lp-tab" data-tab="friction">Friction</button><button class="lp-tab" data-tab="heatmaps">Heatmaps</button></div>
 <section class="lp-panel active" data-panel="live"><div class="lp-card"><div class="lp-card-h"><b>Visitors online now</b><span style="font-size:9px;color:#8290a3">Auto-refreshes every 5 seconds</span></div><div class="lp-table-wrap"><table class="lp-table"><thead><tr><th>Visitor</th><th>Location</th><th>Device</th><th>Current page</th><th>Stage</th><th>Pages</th><th>Duration</th><th>Last seen</th><th>Status</th><th></th></tr></thead><tbody id="liveBody"><tr><td colspan="10" class="lp-load">Loading live visitors…</td></tr></tbody></table></div></div></section>
 <section class="lp-panel" data-panel="recorded"><div class="lp-card"><div class="lp-card-h"><b>Recorded Sessions</b><div class="lp-tools"><select class="lp-filter" id="fDevice"><option value="">All devices</option><option>Desktop</option><option>Mobile</option><option>Tablet</option></select><select class="lp-filter" id="fStage"><option value="">All stages</option><option>Home</option><option>Searching Flights</option><option>Flight Results</option><option>Passenger Details</option><option>Payment</option><option>Confirmation</option></select><input class="lp-filter" id="fPath" placeholder="Page path"></div></div><div class="lp-table-wrap"><table class="lp-table"><thead><tr><th>Visitor</th><th>Started</th><th>Location</th><th>Device</th><th>Entry/Current</th><th>Stage</th><th>Pages</th><th>Duration</th><th>Status</th><th></th></tr></thead><tbody id="recordBody"><tr><td colspan="10" class="lp-load">Loading recordings…</td></tr></tbody></table></div></div></section>
 <section class="lp-panel" data-panel="journeys"><div class="lp-analytics"><div class="lp-mini"><h3>Top visitor journeys</h3><div class="lp-list" id="journeyList"></div></div><div class="lp-mini"><h3>Funnel stages</h3><div class="lp-list" id="stageList"></div></div></div></section>
 <section class="lp-panel" data-panel="friction"><div class="lp-analytics"><div class="lp-mini"><h3>Friction signals</h3><div class="lp-list" id="frictionList"></div></div><div class="lp-mini"><h3>What the signals mean</h3><div class="lp-list"><div class="lp-row"><b>Rage Click</b><span>Repeated clicks in same area</span></div><div class="lp-row"><b>Dead Click</b><span>Click with no visible DOM/navigation reaction</span></div><div class="lp-row"><b>Form Interaction</b><span>Form field focused; value is never recorded</span></div><div class="lp-row"><b>JS Error</b><span>Browser JavaScript error signal</span></div></div></div></div></section>
 <section class="lp-panel" data-panel="heatmaps"><div class="lp-card"><div class="lp-card-h"><b>Click Heatmap</b><div class="lp-tools"><select class="lp-filter" id="heatPath"></select><button class="lp-btn" id="loadHeat">Load Heatmap</button></div></div><div style="padding:16px"><div class="lp-heat" id="heatCanvas"><div class="lp-empty">Choose a tracked page to visualize click concentration.</div></div></div></div></section>
</div>
<div class="lp-drawer" id="lpDrawer"><div class="lp-drawer-h"><b>Visitor Session</b><button class="lp-close" id="lpClose">×</button></div><div class="lp-drawer-b" id="lpDrawerBody"></div></div>
<script>
(function(){
const DATA='{{ route('crm.live_pax_data') }}', SESSION='{{ url('/live-pax/session') }}';
let state={from:'',to:'',payload:null}; const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
function iso(d){return d.toISOString().slice(0,10)} function setRange(days){let t=new Date(),f=new Date();if(days==='today'){}else f.setDate(t.getDate()-(Number(days)-1));$('#lpFrom').value=iso(f);$('#lpTo').value=iso(t);load()}
setRange(7);
$$('[data-quick]').forEach(b=>b.onclick=()=>setRange(b.dataset.quick)); $('#lpApply').onclick=load; ['#fDevice','#fStage','#fPath'].forEach(s=>$(s).addEventListener('change',load));$('#fPath').addEventListener('keyup',e=>{if(e.key==='Enter')load()});
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===b.dataset.tab))});
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))} function dur(n){n=Math.max(0,Number(n)||0);let h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=Math.floor(n%60);return h?h+'h '+m+'m':m?m+'m '+s+'s':s+'s'} function dt(s){if(!s)return '—';return new Date(String(s).replace(' ','T')+'Z').toLocaleString()} function stat(s){let c=s==='Active'?'lp-active':s==='Idle'?'lp-idle':'lp-offline';return '<span class="lp-status '+c+'">'+esc(s)+'</span>'}
async function load(){state.from=$('#lpFrom').value;state.to=$('#lpTo').value;let q=new URLSearchParams({from:state.from,to:state.to,device:$('#fDevice').value,stage:$('#fStage').value,path:$('#fPath').value});try{let r=await fetch(DATA+'?'+q,{credentials:'same-origin'}),p=await r.json();state.payload=p;render(p)}catch(e){}}
function render(p){let s=p.stats||{};$('#kOnline').textContent=s.online||0;$('#kActive').textContent=s.active||0;$('#kIdle').textContent=s.idle||0;$('#kResults').textContent=s.results||0;$('#kPayment').textContent=s.payment||0;renderSessions(p.live||[],true);renderSessions(p.recorded||[],false);renderAnalytics(p.analytics||{})}
function renderSessions(rows,live){let body=$(live?'#liveBody':'#recordBody');if(!rows.length){body.innerHTML='<tr><td colspan="10"><div class="lp-empty">No sessions found.</div></td></tr>';return}body.innerHTML=rows.map(r=>{let id=esc(String(r.visitor_key||'').slice(-10)),loc=esc([r.city,r.country].filter(Boolean).join(', ')||'Unknown'),dev=esc((r.device_type||'Unknown')+' · '+(r.browser||'')),path='<div class="lp-path" title="'+esc(r.current_path)+'">'+esc(r.current_path||'/')+'</div>',watch='<a class="lp-btn" href="'+SESSION+'/'+r.id+'/replay">'+(live?'Watch Live':'Replay')+'</a> <button class="lp-btn alt" onclick="window.lpDetail('+r.id+')">Details</button>';return '<tr><td><span class="lp-id">PX-'+id+'</span></td>'+(live?'':'<td>'+dt(r.started_at)+'</td>')+'<td>'+loc+'</td><td>'+dev+'</td><td>'+path+'</td><td>'+esc(r.funnel_stage||'Browsing')+'</td><td>'+esc(r.pages_visited||0)+'</td><td>'+dur(r.duration_seconds)+'</td>'+(live?'<td>'+esc(r.last_seen_seconds)+'s ago</td>':'')+'<td>'+stat(r.status)+'</td><td>'+watch+'</td></tr>'}).join('')}
function renderAnalytics(a){let list=(sel,rows,key,val)=>{$(sel).innerHTML=(rows||[]).length?(rows||[]).map(r=>'<div class="lp-row"><b>'+esc(r[key]||'Unknown')+'</b><span>'+esc(r[val]||0)+'</span></div>').join(''):'<div class="lp-empty">No data in this range.</div>'};list('#journeyList',a.journeys,'journey','sessions');list('#stageList',a.stages,'funnel_stage','views');list('#frictionList',a.friction,'event_type','total');let hp=$('#heatPath');hp.innerHTML=(a.top_pages||[]).map(r=>'<option value="'+esc(r.path)+'">'+esc(r.path)+' · '+esc(r.views)+' views</option>').join('')||'<option value="/">/</option>'}
window.lpDetail=async function(id){let r=await fetch(SESSION+'/'+id,{credentials:'same-origin'}),p=await r.json(),s=p.session||{},pages=p.pages||[],f=p.friction||{};$('#lpDrawerBody').innerHTML='<div class="lp-detail-grid">'+[['Anonymous ID','PX-'+String(s.visitor_key||'').slice(-12)],['Location',[s.city,s.region,s.country].filter(Boolean).join(', ')||'Unknown'],['Device',(s.device_type||'')+' · '+(s.browser||'')],['OS',s.operating_system||'Unknown'],['Source',s.source||'Direct'],['Started',dt(s.started_at)],['Current page',s.current_path||'/'],['Pages',s.pages_visited||0]].map(x=>'<div class="lp-detail"><small>'+esc(x[0])+'</small><b>'+esc(x[1])+'</b></div>').join('')+'</div><div class="lp-timeline"><h3 style="font-size:12px;color:#173758">Page History</h3>'+pages.map(x=>'<div class="lp-step"><b>'+esc(x.funnel_stage||x.page_title||'Page')+'</b>'+esc(dt(x.entered_at))+' · '+esc(x.path)+'</div>').join('')+'</div><a class="lp-btn" style="margin-top:8px" href="'+SESSION+'/'+id+'/replay">Open Session Replay</a>';$('#lpDrawer').classList.add('open')};$('#lpClose').onclick=()=>$('#lpDrawer').classList.remove('open');
$('#loadHeat').onclick=async()=>{let q=new URLSearchParams({from:state.from,to:state.to,path:$('#heatPath').value});let r=await fetch('{{ route('crm.live_pax_heatmap') }}?'+q),p=await r.json(),c=$('#heatCanvas');c.innerHTML='';if(!p.points||!p.points.length){c.innerHTML='<div class="lp-empty">No click points for this page/date range.</div>';return}let maxY=Math.max(520,...p.points.map(x=>Number(x.y)||0))+50;c.style.minHeight=Math.min(maxY,1800)+'px';p.points.slice(0,1500).forEach(x=>{let d=document.createElement('i');d.className='lp-dot';d.style.left=x.x+'%';d.style.top=Math.min(Number(x.y)||0,1750)+'px';c.appendChild(d)})};
setInterval(()=>{if(document.visibilityState==='visible')load()},5000);
})();
</script>
@endsection
